const $=s=>document.querySelector(s),key='leite-drafts-v1';let records=[];try{records=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(records))records=[];}catch{$('#message').textContent='Não foi possível recuperar os rascunhos locais.';}
function message(t){$('#message').textContent=t;}
function persist(){try{localStorage.setItem(key,JSON.stringify(records));return true;}catch{message('O navegador não permitiu salvar. Exporte uma cópia agora.');return false;}}
function clear(){ $('#editor').reset();$('#record-id').value='';}
function render(){$('#saved-list').replaceChildren();if(!records.length){$('#saved-list').textContent='Nenhum rascunho salvo ainda.';return;}records.forEach(r=>{const row=document.createElement('div'),name=document.createElement('strong');name.textContent=r.title;const edit=document.createElement('button');edit.textContent='Editar';edit.onclick=()=>{$('#record-id').value=r.id;$('#title').value=r.title;$('#category').value=r.category;$('#body').value=r.body;$('#demo').checked=r.demo;$('#title').focus();};const del=document.createElement('button');del.textContent='Excluir';del.onclick=()=>{if(confirm('Excluir o rascunho “'+r.title+'”?')){records=records.filter(x=>x.id!==r.id);persist();if($('#record-id').value===r.id)clear();render();}};row.append(name,edit,del);$('#saved-list').append(row);});}
$('#editor').onsubmit=e=>{e.preventDefault();const title=$('#title').value.trim(),body=$('#body').value.trim();if(!title||!body){message('Preencha título e texto.');return;}const r={id:$('#record-id').value||crypto.randomUUID(),title,body,category:$('#category').value,demo:$('#demo').checked};const i=records.findIndex(x=>x.id===r.id);if(i<0)records.push(r);else records[i]=r;const saved=persist();render();$('#record-id').value=r.id;if(saved)message('Rascunho salvo neste navegador. O site publicado não foi alterado.');};
$('#new').onclick=()=>{clear();message('Novo rascunho.');};$('#preview').onclick=()=>{$('#preview-title').textContent=$('#title').value||'Sem título';$('#preview-body').textContent=$('#body').value||'Seu texto aparecerá aqui.';$('#preview-dialog').showModal();};$('.close').onclick=()=>$('#preview-dialog').close();
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({articles:records},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='content.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Cópia exportada. Guarde o arquivo antes de limpar o navegador.');};
$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('Arquivo muito grande (máximo 2 MB).');const data=JSON.parse(await f.text());if(!Array.isArray(data.articles)||data.articles.length>200)throw Error('Formato inválido: esperado articles com até 200 registros.');const incoming=data.articles.map(r=>{if(typeof r.title!=='string'||!r.title.trim()||r.title.length>120||typeof r.body!=='string'||r.body.length>20000||!['Luz e sombra','Animais','Estátuas','Composição','Diário'].includes(r.category)||typeof r.demo!=='boolean')throw Error('Há um registro inválido. Nenhum conteúdo foi importado.');return {id:crypto.randomUUID(),title:r.title,body:r.body,category:r.category,demo:r.demo};});records.push(...incoming);if(persist())message('Cópia importada e adicionada aos rascunhos existentes.');render();}catch(err){message(err.message||'Não foi possível importar o arquivo.');}finally{e.target.value='';}};render();
